// Hero photo cropped from the approved member hub mockup.
// Served by the Worker so the page does not hotlink.
const FILE = {
  path: "/assets/hub-hero.jpg",
  type: "image/jpeg",
  base64: "",
};

export function hubHero(requestPath) {
  if (requestPath !== FILE.path) return null;
  const binary = atob(FILE.base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return { type: FILE.type, bytes };
}
